(async function() {
  let state = await lf.ready;
  let currentQuizRecord = null;
  let sessionScore = 0;
  let sessionTotal = 0;

  const previewNotice = document.getElementById('previewNotice');
  const quizSection = document.getElementById('quizSection');
  const historySection = document.getElementById('historySection');
  const savedContainer = document.getElementById('savedContainer');
  const quizContent = document.getElementById('quizContent');
  const scoreVal = document.getElementById('scoreVal');
  const totalVal = document.getElementById('totalVal');

  if (state.preview) {
    previewNotice.textContent = \"Preview only. Publish to save changes.\";
    previewNotice.style.display = \"block\";
  }

  document.querySelectorAll('.tab-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      const tab = btn.getAttribute('data-tab');
      if (tab === 'quiz') {
        quizSection.style.display = 'block';
        historySection.style.display = 'none';
      } else {
        quizSection.style.display = 'none';
        historySection.style.display = 'block';
      }
    });
  });

  function pickNewQuizRecord(records) {
    if (!records || records.length === 0) {
      currentQuizRecord = null;
    } else {
      const randomIndex = Math.floor(Math.random() * records.length);
      currentQuizRecord = records[randomIndex];
    }
    renderQuiz();
  }

  function renderQuiz() {
    const records = state.records || [];
    if (records.length === 0) {
      quizContent.innerHTML = '<div class=\"empty-state\">No saved calculations found in history to build a quiz from. Add calculations or wait for records.</div>';
      return;
    }

    if (!currentQuizRecord) {
      pickNewQuizRecord(records);
      return;
    }

    const v = currentQuizRecord.values || {};
    quizContent.innerHTML = `
      <div class=\"quiz-card\">
        <p style=\"font-weight:700; margin-bottom:0.5rem;\">Ingredient: <span style=\"color:var(--coral);\">${escapeHtml(v.ingredient || 'Ingredient')}</span></p>
        <p>Original Amount: <strong>${escapeHtml(String(v.amount ?? ''))}</strong></p>
        <p>Original Servings: <strong>${escapeHtml(String(v.originalServings ?? ''))}</strong></p>
        <p>Target Servings: <strong>${escapeHtml(String(v.targetServings ?? ''))}</strong></p>
      </div>

      <div class=\"field\">
        <label for=\"guessInput\">Your Guessed Scaled Amount</label>
        <input type=\"number\" step=\"any\" id=\"guessInput\" placeholder=\"Enter scaled amount\" />
      </div>

      <div class=\"btn-row\">
        <button type=\"button\" id=\"checkBtn\" class=\"primary\">Check Answer</button>
        <button type=\"button\" id=\"nextBtn\" class=\"primary\" style=\"background:var(--ink);\" disabled>Next Question</button>
      </div>

      <div id=\"quizFeedback\" style=\"display:none;\"></div>
    `;

    const checkBtn = document.getElementById('checkBtn');
    const nextBtn = document.getElementById('nextBtn');
    const guessInput = document.getElementById('guessInput');
    const quizFeedback = document.getElementById('quizFeedback');

    checkBtn.addEventListener('click', async () => {
      const guessVal = parseFloat(guessInput.value);
      if (isNaN(guessVal)) {
        quizFeedback.textContent = \"Please enter a valid number.\";
        quizFeedback.className = \"feedback-box incorrect\";
        quizFeedback.style.display = 'block';
        return;
      }

      if (!state.permissions.canUseTools && state.preview) {
        quizFeedback.textContent = \"Preview only: Publish to run tool.\";
        quizFeedback.className = \"feedback-box incorrect\";
        quizFeedback.style.display = 'block';
        return;
      }

      try {
        checkBtn.disabled = true;
        checkBtn.textContent = \"Checking...\";
        const res = await lf.runTool(\"scale_recipe\", 1, {
          amount: Number(v.amount),
          originalServings: Number(v.originalServings),
          targetServings: Number(v.targetServings)
        });

        const correctAmount = res.result.scaledAmount;
        sessionTotal++;
        totalVal.textContent = sessionTotal;

        if (Math.abs(guessVal - correctAmount) < 0.01) {
          sessionScore++;
          scoreVal.textContent = sessionScore;
          quizFeedback.textContent = `Correct! Exact scaled amount is ${correctAmount}.`;
          quizFeedback.className = \"feedback-box correct\";
        } else {
          quizFeedback.textContent = `Try again! The correct scaled amount is ${correctAmount}. (Your guess: ${guessVal})`;
          quizFeedback.className = \"feedback-box incorrect\";
        }
        quizFeedback.style.display = 'block';
        nextBtn.disabled = false;
      } catch (err) {
        quizFeedback.textContent = \"Tool error: \" + (err.message || err);
        quizFeedback.className = \"feedback-box incorrect\";
        quizFeedback.style.display = 'block';
      } finally {
        checkBtn.disabled = false;
        checkBtn.textContent = \"Check Answer\";
      }
    });

    nextBtn.addEventListener('click', () => {
      pickNewQuizRecord(records);
    });
  }

  function renderHistory(currentState) {
    const records = currentState.records || [];
    if (records.length === 0) {
      savedContainer.innerHTML = '<div class=\"empty-state\">No saved calculations yet.</div>';
      return;
    }

    let html = `<table><thead><tr><th>Ingredient</th><th>Amount</th><th>Orig. Serv.</th><th>Target Serv.</th><th>Scaled</th><th>Action</th></tr></thead><tbody>`;
    for (const r of records) {
      const v = r.values || {};
      html += `<tr>\n        <td>${escapeHtml(v.ingredient || '')}</td>\n        <td>${escapeHtml(String(v.amount || ''))}</td>\n        <td>${escapeHtml(String(v.originalServings || ''))}</td>\n        <td>${escapeHtml(String(v.targetServings || ''))}</td>\n        <td><strong>${escapeHtml(String(v.scaledAmount || ''))}</strong></td>\n        <td><button data-id=\"${r.id}\" class=\"del-btn primary\" style=\"padding:0.25rem 0.5rem;font-size:0.8rem;background:#b84332;\">Delete</button></td>\n      </tr>`;
    }
    html += `</tbody></table>`;
    savedContainer.innerHTML = html;

    savedContainer.querySelectorAll('.del-btn').forEach(btn => {
      btn.addEventListener('click', async () => {
        const id = btn.getAttribute('data-id');
        try {
          state = await lf.remove(id);
          renderHistory(state);
          renderQuiz();
        } catch (err) {
          alert(\"Failed to delete: \" + (err.message || err));
        }
      });
    });
  }

  function escapeHtml(str) {
    return str.replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\");
  }

  renderQuiz();
  renderHistory(state);

  lf.subscribe(next => {
    state = next;
    renderHistory(state);
    if (!currentQuizRecord && state.records && state.records.length > 0) {
      renderQuiz();
    }
  });

  await lf.reportReady();
})();

